bool trace_level_control::start(std::string process, std::filesystem::path file, std::chrono::milliseconds interval) {
	if(state_ || !known_process(process) || interval.count() <= 0) return false;
	if(file.empty()) {
		const auto env = std::getenv("STM_LOG_LEVEL_FILE");
		file = env && *env ? env : "/run/stm/log-levels.json";
	}
	if(!file.is_absolute()) return false;
	bool expected = false;
	if(!controller_active.compare_exchange_strong(expected, true)) return false;
	try {
		auto next = std::make_unique<implementation>();
		next->process = std::move(process);
		next->file = std::move(file);
		next->interval = interval;
"}
